二、单链表的操作实现
定义单链表结点的结构体如下 :
  typedef struct Node
  {
      DataType data;
      struct Node *next;
  }SLNode;
1、初始化
void ListInitiate(SLNode **head) / * 初始化 */
{ /* 如果有内存空间,申请头结点空间并使头指针 head 指向
  头结点 */
  if((*head = (SLNode *)malloc(sizeof(SLNode))) == NUL
  L) exit(1);
  (*head)->next = NULL;      /* 置链尾标记 NULL */
}

