2、求单链表中数据元素的个数

int ListLength(SLNode *head)
{
     SLNode *p = head; /*p 指向头结点 */
     int size = 0;     /*size 初始为 0*/
     while(p->next != NULL) /* 循环计数 */
     {
          p = p->next;
          size ++;
     }
     return size;
}

