int ListDelete(SLNode *head, int i, DataType *x)
   { SLNode *p, *s;      int j;
(1)    p = head; j = -1;
       while(p->next != NULL && p->next->next!= NULL &&
  j < i - 1)
       {     p = p->next;      j++; }
       if(j != i - 1)
       { printf(“ 插入位置参数错!” ); return 0;
}
(2) s = p->next;
       *x = s->data;
(3)     p->next = p->next->next;
       free(s);
       return 1;
     }

